\section{The presheaf of records}

Throughout, fix types $K$ (keys) and $\Val$ (values).

\begin{definition}[Record]
For a set of keys $U \subseteq K$, a \emph{record over $U$} is a function
$s : U \to \Val$. We write $\Record(K,\Val,U)$ for the type of such records. A
\emph{database} over $U$ is a record over $U$; a database with missing entries is
a record over the proper subset of filled keys.
\end{definition}

\begin{definition}[Restriction]
For key sets $W \subseteq U$ and $s \in \Record(K,\Val,U)$, the restriction is
\[ (\restrict_{W \subseteq U} s)(x) = s(x), \qquad x \in W. \]
\end{definition}

\begin{proposition}[Identity law, \texttt{restrict\_self}]
For any $s$ over $U$, $\restrict_{U \subseteq U} s = s$.
\end{proposition}
\begin{proof}
Pointwise both sides evaluate $s$ at $x$; extensionality concludes.
\end{proof}

\begin{proposition}[Composition law, \texttt{restrict\_restrict}]
For $X \subseteq W \subseteq U$ and $s$ over $U$,
\[ \restrict_{X \subseteq W}\big(\restrict_{W \subseteq U} s\big)
   = \restrict_{X \subseteq U} s. \]
\end{proposition}
\begin{proof}
Both sides evaluate $s$ at the image of $x \in X$ under the composite inclusion
$X \hookrightarrow U$; the composite inclusions agree.
\end{proof}

\section{The sheaf condition}

We consider \emph{covers}: families of key sets indexed by an arbitrary type $I$.

\begin{definition}[Overlap-consistency, \texttt{Consistent}]
For a family $S : I \to \mathcal{P}(K)$ and records $r_i$ over $S_i$, the family
is \emph{overlap-consistent} if
\[ \Consistent(S,r) :\equiv \forall i,j,\ \forall x \in S_i \cap S_j,\quad
   r_i(x) = r_j(x). \]
\end{definition}

\begin{theorem}[Separation, \texttt{glue\_eq\_of\_locally\_eq}]
Let $S : I \to \mathcal{P}(K)$ be a cover and $g,g'$ records over
$\bigcup_i S_i$. If for all $i$,
$\restrict_{S_i} g = \restrict_{S_i} g'$, then $g = g'$.
\end{theorem}
\begin{proof}
Fix $x \in \bigcup_i S_i$; choose $i$ with $x \in S_i$. The hypothesis at $i$,
evaluated at $x$, gives $g(x) = g'(x)$. Extensionality concludes.
\end{proof}

\begin{theorem}[Gluing---databases form a sheaf, \texttt{exists\_unique\_glue}]
Let $S : I \to \mathcal{P}(K)$ be a cover and $r$ a family with $r_i$ over $S_i$.
If $\Consistent(S,r)$, there is a unique global record $g$ over $\bigcup_i S_i$
with $\restrict_{S_i} g = r_i$ for all $i$:
\[ \exists!\, g,\quad \forall i,\ \restrict_{S_i} g = r_i. \]
\end{theorem}
\begin{proof}
\emph{Existence} is constructive: for $x \in \bigcup_i S_i$ choose $i_x$ with
$x \in S_{i_x}$ and set $g(x) := r_{i_x}(x)$. Restricting to $S_j$ and evaluating
at $x \in S_j$ requires $r_{i_x}(x) = r_j(x)$, which is overlap-consistency at
indices $i_x,j$ and key $x$. \emph{Uniqueness} follows from separation: any two
glues share all restrictions, hence are equal.
\end{proof}

\section{Integrability equals consistency}

\begin{proposition}[Restrictions are consistent, \texttt{consistent\_of\_restrict}]
Let $g$ be over $U$ and $S_i \subseteq U$. Then
$(\restrict_{S_i} g)_i$ is overlap-consistent.
\end{proposition}
\begin{proof}
For $x \in S_i \cap S_j$ both restrictions evaluate $g$ at $x$.
\end{proof}

\begin{theorem}[Integrability $\Leftrightarrow$ consistency, \texttt{exists\_glue\_iff\_consistent}]
For a cover $S$ and family $r$,
\[ \Big(\exists g\ \text{over}\ \textstyle\bigcup_i S_i,\ \forall i,\
   \restrict_{S_i} g = r_i\Big) \iff \Consistent(S,r). \]
\end{theorem}
\begin{proof}
($\Rightarrow$) A glue's restrictions equal $r$ and are consistent by the
previous proposition. ($\Leftarrow$) Apply gluing and forget uniqueness.
\end{proof}

\begin{theorem}[Two-table merge, \texttt{exists\_unique\_merge\_two}]
Let $S_0,S_1 \subseteq K$ with records $r_0$ over $S_0$, $r_1$ over $S_1$. If
$r_0(x) = r_1(x)$ for all $x \in S_0 \cap S_1$, there is a unique record $g$ over
$S_0 \cup S_1$ with $\restrict_{S_0} g = r_0$ and $\restrict_{S_1} g = r_1$.
\end{theorem}
\begin{proof}
Specialize gluing to the two-element cover $S_{\mathrm{false}}=S_0$,
$S_{\mathrm{true}}=S_1$; the hypothesis is two-index overlap-consistency and the
union is $S_0 \cup S_1$.
\end{proof}

\section{The cellular sheaf of a schema graph}

Replace the key space by a schema graph $G=(V,E)$: vertices are data sources,
edges are agreement constraints. Fix a commutative ring $R$.

\begin{definition}[Constant graph sheaf and $H^0$]
The zeroth cohomology of the constant sheaf is the submodule of $V \to R$ of
functions constant along edges:
\[ H^0(G,R) = \{ f : V \to R \mid \forall\, v \sim w,\ f(v)=f(w) \}. \]
A graph sheaf $F$ assigns stalks to vertices and comparison maps to edges; a
vertex-wise assignment is a \emph{global section} when every edge constraint
holds. The consistent integrations form the submodule $\globalSections$.
\end{definition}

\begin{theorem}[Cohomological characterization, \texttt{mem\_H0\_iff\_reachable}]
$f \in H^0(G,R)$ iff $f$ is constant on every reachable pair:
$f \in H^0(G,R) \iff (\forall v,w,\ G.\Reachable(v,w) \Rightarrow f(v)=f(w))$.
\end{theorem}
\begin{proof}
Edge-constancy propagates along walks by induction; adjacency implies
reachability.
\end{proof}

\begin{theorem}[Integrations $=H^0$, \texttt{mkConstantSheaf\_section\_iff\_H0}]
For the constant sheaf, $f$ is a global section iff $f \in H^0(G,R)$.
\end{theorem}

\begin{theorem}[Connected rigidity, \texttt{H0\_eq\_const\_of\_connected}]
If $G$ is connected, $H^0(G,R) = \{ f : V \to R \mid f \text{ constant} \}$.
\end{theorem}
\begin{proof}
Reachability is total on a connected graph, so every $f \in H^0$ is constant by
the previous characterization; constants always lie in $H^0$.
\end{proof}

\begin{theorem}[Evaluation injectivity, \texttt{globalSections\_eval\_injective\_of\_connected}]
Over a connected $G$, the evaluation $\globalSections \to R$, $f \mapsto f(v_0)$,
is injective for any base vertex $v_0$.
\end{theorem}
\begin{proof}
A global section is constant (connected rigidity) and is recovered from its value
anywhere.
\end{proof}

\begin{theorem}[Dimension count, \texttt{finrank\_H0\_eq\_card\_connectedComponent}]
Over a field $k$, $\dim_k H^0(G,k)$ equals the number of connected components of
$G$.
\end{theorem}
\begin{proof}
$H^0$ is isomorphic to functions on the set of connected components; take
dimensions.
\end{proof}

\section{Quantitative imputation model}

A database with missing entries is a partial section: a record on the filled keys
$U_{\mathrm{obs}}$. \emph{Sheaf imputation} extends it to a global section closest
to the observed values:
\[ \min_{g}\ \mathrm{dist}\big(g|_{U_{\mathrm{obs}}}, s_{\mathrm{obs}}\big)
   \quad \text{s.t.}\quad \Consistent\ \text{on every overlap}. \]
Unlike mean or $k$-NN imputation, this enforces all overlap constraints at once.

\begin{conjecture}[Feasibility law]
If entries are missing independently at rate $r$ and there are $C$ overlapping
consistency constraints (e.g. $C=\binom{n}{k}$ for $n$ columns and $k$ rows),
then the probability that a random partial database admits a consistent
completion is
\[ P(\text{sheaf}) = (1-r)^{C}. \]
\end{conjecture}

Each independent constraint survives with probability $1-r$, and feasibility
requires all $C$ jointly. This predicts (i) consistent completion becomes
exponentially rare as overlaps grow, and (ii) a genuinely consistent dataset
carries exponentially more imputation information than local methods exploit,
yielding the testable claim that sheaf imputation beats mean/KNN/MICE for
$r<0.5$, $n>10$.

\section{Discussion and future work}

\begin{conjecture}[$H^1$ obstruction]
With cellular $1$-cochains and coboundary $\delta^0 : C^0(G,F)\to C^1(G,F)$, a
consistent integration extending prescribed edge-agreements exists iff its class
in $H^1(G,F)=\ker\delta^1/\im\delta^0$ vanishes; for the constant sheaf,
$\dim H^1 = b_1$ (the first Betti number). Cyclic schemas with an edge-twist
obstruct; acyclic schemas always integrate.
\end{conjecture}

\begin{conjecture}[Unique integration $\Leftrightarrow$ acyclic schema]
For the constant sheaf over a nontrivial ring, evaluation-at-a-vertex is
bijective for every base vertex iff $G$ is a tree (once gauge maps are admitted).
\end{conjecture}

\begin{conjecture}[Finite gluing suffices]
For the database sheaf, pairwise consistency on all $S_i\cap S_j$ implies global
consistency, upgrading the two-table merge to arbitrary covers; nontrivial
transition maps are conjectured to be the boundary where this fails.
\end{conjecture}

\begin{conjecture}[Privacy/leakage bound]
Modeling secret sharing as a graph sheaf with share-space stalks, an unauthorized
coalition $T$ learns nothing iff $\globalSections(F)\to\prod_{v\in T}\Stalk(v)$ is
not injective on the secret coordinate---recasting access structures as
cohomological injectivity.
\end{conjecture}

\section{Conclusion}

``Databases form a sheaf'' is a theorem. The presheaf of partial records
satisfies functoriality, separation, and gluing; mergeability is exactly
overlap-consistency; and the schema-graph picture renders integration as zeroth
cohomology, rigid over connected schemas and quantified by component count. These
results ground consistent imputation, a quantitative feasibility law, and a path
to an obstruction theory and cryptographic leakage bounds.

