import matplotlib.pyplot as plt
from collections import deque

def components(graph):
    seen, comps = set(), 0
    for s in graph:
        if s in seen: continue
        comps += 1; q = deque([s]); seen.add(s)
        while q:
            v = q.popleft()
            for w in graph[v]:
                if w not in seen: seen.add(w); q.append(w)
    return comps

